/**
 * 字体名注册表的 ambient 类型面渲染器（`font` 全局常量字面量类型）。
 *
 * 输出 = `Stories.src/gen/font.gen.d.ts` 全文：`declare const font` 的键与值都取
 * 注册表字体名（引号键保非标识符名可用），未注册名在 TS 面即不存在——IDE 补全只给
 * 正名，改拼直接 TS2551。纯编译期声明，不注入运行时对象；模块自有 `font` 声明按
 * TS 遮蔽语义优先。空注册表产出 `Record<never, never>`：TS 里空对象字面量 `{}` 会
 * 放开任意键访问，等于放弃改拼保护，这里必须给封闭空类型。
 */

import type { FontEntry } from "../fonts/font-registry.ts";

const HEADER = [
  "/* GENERATED by stories:build (font-typegen) — 构建期自动生成，手改会在下次构建被覆盖。",
  "   字体名注册表（Resources/Fonts 文件名去扩展名）的全局字面量类型面：键 = 值 = 字体名；",
  "   未注册名不在本类型面，运行期字符串形态 {font=名} 仍走构建期注册表校验。 */",
].join("\n");

/** 渲染 font.gen.d.ts 全文；空注册表 = 封闭空对象（键访问改拼必报 TS2551） */
export function renderFontTypegen(entries: readonly FontEntry[]): string {
  const lines = entries.map(
    (entry) => `  readonly ${JSON.stringify(entry.name)}: ${JSON.stringify(entry.name)};`,
  );
  const declaration =
    lines.length === 0
      ? "declare const font: Record<never, never>;"
      : ["declare const font: {", ...lines, "};"].join("\n");
  return `${HEADER}\n\n${declaration}\n`;
}
